```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title BurnableToken
 * @notice ERC20 token with secure burn functionality
 * @dev Uses OpenZeppelin v5 patterns — no floating pragma, explicit visibility
 */
contract BurnableToken {
    // ─── Storage ──────────────────────────────────────────────
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;

    uint256 private _totalSupply;
    string private _name;
    string private _symbol;
    uint8 private _immutableDecimals; // immutable-like pattern

    // ─── Events ───────────────────────────────────────────────
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Burn(address indexed burner, uint256 value);

    // ─── Errors (gas-efficient, no string storage) ───────────
    error ERC20InsufficientBalance(address sender, uint256 balance, uint256 needed);
    error ERC20InvalidSender(address sender);
    error ERC20InvalidReceiver(address receiver);
    error ERC20InvalidSpender(address spender);
    error ERC20InvalidApprover(address approver);
    error ERC20InsufficientAllowance(address spender, uint256 allowance, uint256 needed);
    error BurnExceedsBalance(address burner, uint256 balance, uint256 amount);

    // ─── Constructor ──────────────────────────────────────────
    constructor(
        string memory name_,
        string memory symbol_,
        uint8 decimals_,
        uint256 initialSupply
    ) {
        _name = name_;
        _symbol = symbol_;
        _immutableDecimals = decimals_;

        // Mint initial supply to deployer
        _mint(msg.sender, initialSupply);
    }

    // ─── ERC20 Public Interface ───────────────────────────────
    function name() public view returns (string memory) { return _name; }
    function symbol() public view returns (string memory) { return _symbol; }
    function decimals() public view returns (uint8) { return _immutableDecimals; }
    function totalSupply() public view returns (uint256) { return _totalSupply; }
    function balanceOf(address account) public view returns (uint256) { return _balances[account]; }

    function transfer(address to, uint256 value) public returns (bool) {
        address owner = msg.sender;
        _transfer(owner, to, value);
        return true;
    }

    function allowance(address owner, address spender) public view returns (uint256) {
        return _allowances[owner][spender];
    }

    function approve(address spender, uint256 value) public returns (bool) {
        address owner = msg.sender;
        _approve(owner, spender, value, true);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) public returns (bool) {
        address spender = msg.sender;
        _spendAllowance(from, spender, value);
        _transfer(from, to, value);
        return true;
    }

    // ── Burn ──────────────────────────────────────────────────
    /**
     * @notice Quema tokens del balance propio del caller
     * @dev Solo el holder puede quemar sus propios tokens.
     *      Esto previene que terceros quemen tokens ajenos (ataque de griefing).
     *      Emite evento Burn + Transfer(to=0) para compatibilidad con explorers.
     */
    function burn(uint256 amount) public {
        address burner = msg.sender;
        uint256 balance = _balances[burner];

        // Check-effects-interactions pattern (no external calls after state change)
        if (balance < amount) {
            revert BurnExceedsFrom(burner, balance, amount);
        }

        // Efecto: actualizar estado ANTES de eventos
        unchecked {
            // SafeMath built-in via Solidity 0.8.x overflow checks
            _balances[burner] = balance - amount;
            _totalSupply -= amount;
        }

        emit Transfer(burner, address(0), amount);
        emit Burn(burner, amount);
    }

    /**
     * @notice Burn tokens desde otra dirección (requiere allowance)
     * @dev Útil para contratos que necesitan quemar tokens de usuarios
     *      (ej: stablecoin redemption, staking penalty)
     */
    function burnFrom(address from, uint256 amount) public {
        address spender = msg.sender;
        uint256 balance = _balances[from];

        if (balance < amount) {
            revert BurnExceedsFrom(from, balance, amount);
        }

        // Gasta allowance del spender
        _spendAllowance(from, spender, amount);

        // Burn effects
        _balances[from] = balance - amount;
        _totalSupply -= amount;

        emit Transfer(from, address(0), amount);
        emit Burn(from, amount);
    }

    // ── Internal ──────────────────────────────────────────────
    function _transfer(address from, address to, uint256 value) internal {
        if (from == address(0)) revert ERC20InvalidSender(address(0));
        if (to == address(0)) revert ERC20InvalidReceiver(address(0));

        uint256 fromBalance = _balances[from];
        if (fromBalance < value) {
            revert ERC20InsufficientBalance(from, fromBalance, value);
        }

        // Check-effects-interactions
        _balances[from] = fromBalance - value;
        _balances[to] += value;

        emit Transfer(from, to, value);
    }

    function _mint(address account, uint256 value) internal {
        if (account == address(0)) revert ERC20InvalidReceiver(address(0));

        _totalSupply += value;
        _balances[account] += value;

        emit Transfer(address(0), account, value);
    }

    function _approve(address owner, address spender, uint256 value, bool emitEvent) internal {
        if (owner == address(0)) revert ERC20InvalidApprover(address(0));
        if (spender == address(0)) revert ERC20InvalidSpender(address(0));

