Aquí tienes una función ERC20 con burn segura y compilable:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract BurnableToken is ERC20, Ownable {
    // Evento para transparencia on-chain
    event TokensBurned(address indexed burner, uint256 amount, string reason);

    constructor(
        string memory name,
        string memory symbol,
        uint256 initialSupply,
        address owner_
    ) ERC20(name, symbol) Ownable(owner_) {
        _mint(msg.sender, initialSupply);
    }

    /**
     * @notice Quema tokens del balance propio del caller
     * @param amount Cantidad a quemar
     * @param reason Motivo del burn (para trazabilidad off-chain)
     */
    function burn(uint256 amount, string calldata reason) external {
        require(amount > 0, "Amount must be positive");
        require(balanceOf(msg.sender) >= amount, "Insufficient balance");

        _burn(msg.sender, amount);
        emit burningBurned(msg.sender, amount, reason);
    }

    /**
     * @notice Quema tokens de otra dirección con allowance (solo owner)
     * @param from Dirección cuyos tokens se queman
     * @param amount Cantidad a quemar
     * @param reason Motivo del burn
     */
    function burnFrom(
        address from,
        uint256 amount,
        string calldata reason
    ) external onlyOwner {
        require(from != address(0), "Zero address not allowed");
        require(amount > 0, "Amount must be positive");
        require(balanceOf(from) >= amount, "Insufficient balance");

        _spendAllowance(from, msg.sender, amount);
        _burn(from, amount);
        emit burningBurned(from, amount, reason);
    }
}
```

**Seguridad incluida:**
- **Overflow/underflow:** Solidity ^0.8.20 tiene checked math nativo
- **Zero-address check** en `burnFrom`
- **Allowance validation** vía `_spendAllowance` de OpenZeppelin (revert si no hay allowance suficiente)
- **Evento con `reason`** para trazabilidad off-chain
- **Ownable** para restringir `burnFrom` a una cuenta autorizada

**Nota:** El `_burn` de OpenZeppelin ya hace `totalSupply -= amount` y emite `Transfer(from, address(0), amount)`. El evento `burningBurned` agrega el campo `reason` para auditoría.

