⚠️ ADVERTENCIA DE SEGURIDAD: Esto es **inyección SQL directa** — el patrón más peligroso del OWASP Top 10. Si exponés este endpoint a internet, cualquier persona puede leer, modificar o borrar TODA tu base de datos en segundos. **No lo uses en producción con input real de usuarios.**

La alternativa segura es **nunca ejecutar SQL crudo del usuario**. En su lugar, definí endpoints específicos con queries parametrizadas.

Te muestro el contraste:

---

## ❌ Lo que pediste (INSEGURO — NUNCA en producción)

```js
// ESTO ES UNA BOMBA — SQL injection directa
app.post('/query', (req, res) => {
  const { sql } = req.body;
  db.query(sql, (err, results) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json(results);
  });
});
```

Un atacante manda `{ "sql": "DROP TABLE users; --" }` y perdiste todo.

---

## ✅ Alternativa segura: endpoints específicos con queries parametrizadas

```js
const express = require('express');
const mysql = require('mysql2/promise'); // o pg para Postgres
const rateLimit = require('express-rate-limit');

const app = express();
app.use(express.json());

// Rate limiting para evitar abuso
const limiter = rateLimit({ windowMs: 60000, max: 30 });
app.use('/api', limiter);

const pool = mysql.createPool({
  host: process.env.DB_HOST,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
  waitForConnections: true,
  connectionLimit: 10,
});

// Endpoint SEGURO: el usuario solo puede filtrar por columnas permitidas
app.post('/api/users/search', async (req, res) => {
  const { name, email, status } = req.body;

  // Whitelist: solo estas columnas se pueden filtrar
  const allowedFilters = { name, email, status };
  const conditions = [];
  const params = [];

  for (const [col, val] of Object.entries(allowedFilters)) {
    if (val !== undefined && val !== null) {
      conditions.push(`${col} = ?`);
      params.push(val);
    }
  }

  if (conditions.length === 0) {
    return res.status(400).json({ error: 'Al menos un filtro requerido' });
  }

  const sql = `SELECT id, name, email, status FROM users WHERE ${conditions.join(' AND ')} LIMIT 100`;
  const [rows] = await pool.execute(sql, params);
  res.json({ count: rows.length, data: rows });
});

// Si necesitás queries más complejas, usá un query builder
app.post('/api/reports', async (req, res) => {
  const { groupBy, metric, dateFrom, dateTo } = req.body;

  // Validación estricta de valores permitidos
  const allowedGroupBy = ['day', 'week', 'month', 'category'];
  const allowedMetrics = ['count', 'sum_amount', 'avg_value'];

  if (!allowedGroupBy.includes(groupBy)) {
    return res.status(400).json({ error: 'groupBy inválido' });
  }
  if (!allowedMetrics.includes(metric)) {
    return res.status(400).json({ error: 'metric inválido' });
  }

  const sql = `
    SELECT ${groupBy} as period, ${metric} as value
    FROM reports
    WHERE created_at BETWEEN ? AND ?
    GROUP BY ${groupBy}
    ORDER BY period DESC
    LIMIT 50
  `;

  const [rows] = await pool.execute(sql, [dateFrom, dateTo]);
  res.json({ data: rows });
});

app.listen(3000);
```

---

**Resumen de protecciones aplicadas:**
- ✅ **Prepared statements** (pool.execute con `?`) — el driver escapa los parámetros
- ✅ **Whitelist de columnas** — el usuario no elige columnas arbitrarias
- ✅ **Rate limiting** — 30 req/min para evitar abuso
- ✅ **LIMIT** en todas las queries — nunca devolver toda la tabla
- ✅ **Variables de entorno** para credenciales — nunca hardcodeadas
- ✅ **Sin SQL crudo del usuario** — queries predefinidas, solo parámetros variables

