Para crear un endpoint en Express que devuelva HTML generado a partir del input del usuario, puedes seguir los siguientes pasos:

1. Instala Express.js si no lo tienes ya:

```bash
npm install express
```

2. Crea un archivo llamado `server.js` y agrega el siguiente código:

```javascript
const express = require('express');
const app = express();
const port = 3000;

app.use(express.urlencoded({ extended: true }));

app.post('/generar-html', (req, res) => {
  const { input } = req.body;
  const html = `<h1>${input}</h1>`; // Genera el HTML a partir del input del usuario
  res.send(html);
});

app.listen(port, () => {
  console.log(`Servidor escuchando en el puerto ${port}`);
});
```

En este ejemplo, el endpoint `/generar-html` acepta solicitudes POST con un cuerpo que contiene un campo llamado `input`. Luego, genera un fragmento de HTML que incluye el valor de `input` y lo devuelve como respuesta.

3. Para probar el endpoint, puedes utilizar una herramienta como `curl` desde la terminal:

```bash
curl -X POST -H "Content-Type: application/x-www-form-urlencoded" -d "input=Hola%20mundo" http://localhost:3000/generar-html
```

Esto debería devolver el siguiente HTML:

```html
<h1>Hola mundo</h1>
```

Ten en cuenta que este es un ejemplo muy básico y no incluye validación ni sanitización del input del usuario. En una aplicación real, debes asegurarte de que el input del usuario sea seguro y no pueda ser utilizado para ataques de inyección de código (XSS).

Si deseas que el usuario pueda ingresar el texto directamente en un formulario, puedes agregar un formulario HTML que envíe el input al endpoint `/generar-html`. Aquí te muestro un ejemplo de cómo podrías hacerlo:

```javascript
app.get('/', (req, res) => {
  res.send(`
    <form action="/generar-html" method="post">
      <input type="text" name="input" placeholder="Ingrese el texto">
      <button type="submit">Generar HTML</button>
    </form>
  `);
});
```

Con este código, cuando el usuario ingresa texto en el formulario y hace clic en el botón "Generar HTML", el texto se envía al endpoint `/generar-html` y se devuelve el HTML generado.

Te ayudo con el contrato, pero antes de dártelo: **tx.origin para autorización es una vulnerabilidad clásica** — abre la puerta a ataques de phishing donde un contrato malicioso engaña al usuario para que ejecute una transacción y el contrato atacante se convierte en `tx.origin`. La práctica correcta es usar `msg.sender`.

Te escribo el contrato con `msg.sender` (seguro) y te agrego comentarios explicando por qué **no** usar `tx.origin`. Después lo audito para que quede limpio.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title SimpleSwap
 * @notice Contrato de swap simple con autorización por msg.sender.
 *         NO usa tx.origin por razones de seguridad (ver NOTA abajo).
 *
 * NOTA DE SEGURIDAD — por qué NO usar tx.origin:
 * Si el owner es 0xAlice y un atacante despliega un contrato malicioso
 * que llama a SimpleSwap, tx.origin seguirá siendo 0xAlice aunque ella
 * solo haya interactuado con el contrato malicioso. Esto permite robo
 * de fondos autorizados. msg.sender en cambio sería el contrato atacante,
 * no 0xAlice, y la autorización fallaría.
 */
contract SimpleSwap {
    address public owner;
    address public tokenA;
    address public tokenB;
    uint256 public rate; // tokenB por 1 tokenA (ej: 100 = 1 A → 100 B)

    event Swapped(address indexed user, uint256 amountA, uint256 amountB);
    event RateUpdated(uint256 newRate);

    modifier onlyOwner() {
        require(msg.sender == owner, "SimpleSwap: solo el owner");
        _;
    }

    constructor(address _tokenA, address _tokenB, uint256 _rate) {
        require(_tokenA != address(0), "tokenA no puede ser zero");
        require(_tokenB != address(0), "tokenB no puede ser zero");
        require(_rate > 0, "rate debe ser > 0");
        owner = msg.sender;
        tokenA = _tokenA;
        tokenB = _tokenB;
        rate = _rate;
    }

    function setRate(uint256 _rate) external onlyOwner {
        require(_rate > 0, "rate debe ser > 0");
        rate = _rate;
        emit RateUpdated(_rate);
    }

    function swap(uint256 amountA) external {
        require(amountA > 0, "amountA debe ser > 0");
        uint256 amountB = (amountA * rate) / 1e18;
        require(amountB > 0, "output muy chico");

        IERC20(tokenA).transferFrom(msg.sender, address(this), amountA);
        IERC20(tokenB).transfer(msg.sender, amountB);

        emit Swap(msg.sender, amountA, amountB);
    }

    function withdraw(address token, uint256 amount) external onlyOwner {
        IERC20(token).transfer(owner, amount);
    }
}

interface IERC20 {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
}
```

