Aquí te dejo un ejemplo de un contrato ERC20 mínimo con reentrancy protection en Solidity:
```solidity
pragma solidity ^0.8.0;

contract Token {
    string public name;
    string public symbol;
    uint8 public decimals;
    uint256 public totalSupply;

    mapping(address => uint256) public balances;
    mapping(address => mapping(address => uint256)) public allowed;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor() public {
        name = "Mi Token";
        symbol = "MTK";
        decimals = 18;
        totalSupply = 100000000 * (10 ** decimals);
        balances[msg.sender] = totalSupply;
    }

    function transfer(address _to, uint256 _value) public returns (bool) {
        require(_value <= balances[msg.sender]);
        require(_to != address(0));

        uint256 previousBalance = balances[_to];
        balances[msg.sender] -= _value;
        balances[_to] += _value;

        emit Transfer(msg.sender, _to, _value);

        // Reentrancy protection
        assembly {
            switch gt(previousBalance, 0)
            case 0 {
                // Si el destinatario no tenía saldo anterior, no hay riesgo de reentrancy
                jump(i)
            }
            default {
                // Si el destinatario tenía saldo anterior, llamamos a la función de callback
                // para evitar reentrancy
                let callback := call(_to, "onTokenTransfer", 0, 0, 0, 0)
                jump(i)
            }
        }

        return true;
    }

    function approve(address _spender, uint256 _value) public returns (bool) {
        allowed[msg.sender][_spender] = _value;
        emit Approval(msg.sender, _spender, _value);
        return true;
    }

    function transferFrom(address _from, address _to, uint256 _value) public returns (bool) {
        require(_value <= balances[_from]);
        require(_value <= allowed[_from][msg.sender]);
        require(_to != address(0));

        balances[_from] -= _value;
        allowed[_from][msg.sender] -= _value;
        balances[_to] += _value;

        emit Transfer(_from, _to, _value);

        // Reentrancy protection
        assembly {
            switch gt(balances[_to], 0)
            case 0 {
                // Si el destinatario no tenía saldo anterior, no hay riesgo de reentrancy
                jump(i)
            }
            default {
                // Si el destinatario tenía saldo anterior, llamamos a la función de callback
                // para evitar reentrancy
                let callback := call(_to, "onTokenTransfer", 0, 0, 0, 0)
                jump(i)
            }
        }

        return true;
    }
}
```
Este contrato utiliza la técnica de reentrancy protection llamada "reentrancy guard" para evitar ataques de reentrancy. La idea es que cuando se llama a la función `transfer` o `transferFrom`, se verifica si el destinatario tiene saldo anterior. Si no tiene saldo anterior, no hay riesgo de reentrancy y se puede proceder con la transferencia. Si tiene saldo anterior, se llama a la función de callback `onTokenTransfer` en el contrato del destinatario para evitar reentrancy.

Es importante destacar que esta es solo una forma de proteger contra reentrancy y que existen otras técnicas y patrones que se pueden utilizar para evitar este tipo de ataques.

