Te paso una implementación ERC20 completa con burn segura, compilable en Solidity ^0.8.20, usando OpenZeppelin como base para no reinventar la rueda en transferencias y aprobaciones:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/// @title BurnableToken
/// @notice ERC20 con burn propio y burnFrom con allowance, sin depender de ERC20Burnable de OZ
contract BurnableToken is ERC20, Ownable {
    // ──── Eventos ────
    event TokensBurned(address indexed burner, uint256 amount);
    event TokensBurnedFrom(address indexed burner, address indexed from, uint256 amount);

    constructor(
        string memory name_,
        string memory symbol_,
        uint256 initialSupply,
        address owner_
    ) ERC20(name_, symbol_) Ownable(owner_) {
        _mint(msg.sender, initialSupply);
    }

    // ──── Burn directo ────
    /// @notice Quema tokens del caller.
    function burn(uint256 amount) external {
        require(amount > 0, "Cantidad debe ser > 0");
        require(balanceOf(msg.sender) >= amount, "Saldo insuficiente");
        _burn(msg.sender, amount);
        emit TokensBurned(msg.sender, amount);
    }

    // ──── Burn con allowance ────
    /**
     * @notice Quema tokens de `from` usando la allowance que `from` le dio a `msg.sender`.
     * @dev No hereda ERC20Burnable para evitar ambigüedades con el burn directo.
     */
    function burnFrom(address from, uint256 amount) external {
        require(amount > 0, "Cantidad debe ser > 0");
        require(from != address(0), "No se puede quemar de address(0)");
        require(balanceOf(from) >= amount, "Saldo insuficiente en from");

        uint256 currentAllowance = allowance(from, msg.sender);
        require(currentAllowance >= amount, "Allowance insuficiente");

        // Actualizar allowance (protección contra double-spend)
        _approve(from, msg.sender, currentAllowance - amount, true);

        _burn(from, amount);
        emit TokensBurnedFrom(msg.sender, from, amount);
    }

    // ──── Mint (solo owner) ────
    function mint(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "No se puede mintear a address(0)");
        require(amount > 0, "Cantidad debe ser > 0");
        _mint(to, amount);
    }
}
```

## 🔒 Seguridad aplicada

- **Protección contra quema indebida:** `burnFrom` verifica allowance explícitamente y la actualiza **antes** del `_burn` para evitar doble gasto.
- **Zero-address check:** tanto en `burnFrom` como en `mint` se rechaza `address(0)`.
- **Overflow/underflow:** Solidity ≥0.8.0 tiene checked arithmetic por defecto — no hace falta SafeMath.
- **Eventos:** cada quema emite su evento, facilitando trazabilidad on-chain.
- **Ownable:** solo el owner puede mintear nuevos tokens.

