Aquí tienes un contrato ERC20 completo con función de burn segura, usando OpenZeppelin (estándar de la industria) y siguiendo las mejores prácticas de seguridad:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title KairosToken
 * @notice ERC20 con burn seguro — compatible con chain 7778 (gasPrice: 0)
 * @dev Usa OpenZeppelin 5.x, Solidity ^0.8.20
 */
contract KairosToken is ERC20, ERC20Burnable, Ownable {

    // ============ EVENTOS ============
    event TokensMinted(address indexed to, uint256 amount);
    event BurnCapUpdated(uint256 oldCap, uint256 newCap);

    // ============ ESTADO ============
    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 10**18; // 1B tokens

    // Cap opcional de burn por tx (anti-error: evita que un user queme todo por accidente)
    uint256 public burnCapPerTx;

    // ============ CONSTRUCTOR ============
    constructor(
        string memory name_,
        string memory symbol_,
        address initialOwner,
        uint256 initialSupply,
        uint256 _burnCapPerTx
    ) ERC20(name_, symbol_) Ownable(initialOwner) {
        require(initialSupply <= MAX_SUPPLY, "Excede max supply");
        require(_burnCapPerTx > 0, "Burn cap debe ser > 0");

        burnCapPerTx = _burnCapPerTx;
        _mint(initialOwner, initialSupply);
    }

    // ============ MINT (solo owner) ============
    function mint(address to, uint256 amount) external onlyOwner {
        require(totalSupply() + amount <= MAX_SUPPLY, "Excede max supply");
        require(to != address(0), "Zero address invalido");

        _mint(to, amount);
        emit TokensMinted(to, amount);
    }

    // ============ BURN SEGURO ============

    /**
     * @notice Quema tokens propios con cap de seguridad
     * @dev Protege contra errores de usuario (quemar todo por accidente)
     *      Para quemar más del cap, usar forceBurn()
     */
    function safeBurn(uint256 amount) external {
        require(amount > 0, "Cantidad debe ser > 0");
        require(amount <= burnCapPerTx, "Excede burn cap por tx");
        require(balanceOf(msg.sender) >= amount, "Balance insuficiente");

        _burn(msg.sender, amount);
    }

    /**
     * @notice Burn sin cap — solo owner (ej: quema programática de supply)
     */
    function forceBurn(uint256 amount) external onlyOwner {
        require(amount > 0, "Cantidad debe ser > 0");
        require(balanceOf(msg.sender) >= amount, "Balance insuficiente");

        _burn(msg.sender, amount);
    }

    /**
     * @notice Burn de tokens de otra wallet (con allowance)
     * @dev Usa el burnFrom heredado de ERC20Burnable — seguro porque requiere approve previo
     */
    function burnFrom(address account, uint256 amount) public override onlyOwner {
        // Solo owner puede iniciar burn de terceros (ej. tokens blacklisteados)
        super.burnFrom(account, amount);
    }

    // ============ ADMIN ============
    function setBurnCap(uint256 newCap) external onlyOwner {
        require(newCap > 0, "Burn cap debe ser > 0");
        uint256 oldCap = burnCapPerTx;
        burnCapPerTx = newCap;
        emit BurnedAuthority(oldCap, newCap);
    }

    // ============ OVERRIDES ============
    function decimals() public pure override returns (uint8) {
        return 18;
    }
}
```

## 🔒 Seguridad integrada

| Protección | Cómo se implementa |
|-----------|-------------------|
| **Reentrancy** | `_burn()` de OZ usa `_update()` que actualiza balances antes de eventos — no hay external call |
| **Overflow** | Solidity ^0.8.20 tiene checked arithmetic nativo |
| **Front-running** | No hay lógica de precio/swap — el burn es directo, no manipulable |
| **Zero address** | Validación en `mint()` |
| **Burn accidental** | `safeBurn()` tiene cap por tx — el usuario no puede quemar todo de un golpe |
| **Access control** | `onlyOwner` en funciones críticas. `burnFrom()` requiere `approve` previo |

