import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract KairosToken is ERC20, ERC20Burnable, Ownable {
    // Eventos para transparencia on-chain
    event TokensMinted(address indexed to, uint256 amount);
    event BurnCapUpdated(uint256 oldCap, uint256 newCap);

    // Cap opcional de burn por transacción para evitar errores catastróficos
    uint256 public maxBurnPerTx;
    bool public burnCapEnabled = true;

    constructor(
        string memory name,
        string memory symbol,
        uint256 initialSupply,
        address initialOwner,
        uint256 _maxBurnPerTx
    ) ERC20(name, symbol) Ownable(initialOwner) {
        require(initialOwner != address(0), "Owner cannot be zero address");
        require(_maxBurnPerTx > 0, "Max burn per tx must be > 0");

        maxBurnPerTx = _maxBurnPerTx;
        _mint(initialOwner, initialSupply);
    }

    /**
     * @notice Override del burn de OpenZeppelin con cap de seguridad.
     * @dev El cap previene burns accidentales masivos. El owner puede
     *      desactivarlo si el token requiere burns sin límite.
     */
    function burn(uint256 amount) public override {
        if (burnCapEnabled) {
            require(amount <= maxBurnPerTx, "Burn amount exceeds per-tx cap");
        }
        super.burn(amount);
    }

    /**
     * @notice Override del burnFrom con la misma protección
     */
    function burnFrom(address account, uint256 amount) public override {
        if (burnCapEnabled) {
            require(amount <= maxBurnPerTx, "Burn amount exceeds per-tx cap");
        }
        super.burnFrom(account, amount);
    }

    /**
     * @notice Ajusta el cap de burn por transacción (solo owner)
     */
    function setMaxBurnPerTx(uint256 _newCap) external onlyOwner {
        require(_newCap > 0, "Cap must be > 0");
        uint256 oldCap = maxBurnPerTx;
        maxBurnPerTx = _newCap;
        emit TokensBurnUpdated(oldCap, _newCap);
    }

    /**
     * @notice Activa o desactiva el cap de burn (solo owner)
     */
    function setBurnCapEnabled(bool _enabled) external onlyOwner {
        burnCapEnabled = _enabled;
    }
}
