Aquí tienes una función Swift moderna con `async/await` que devuelve `Result<Data, Error>`:

```swift
import Foundation

enum APIError: Error {
    case invalidURL
    case invalidResponse
    case httpError(statusCode: Int)
    case decodingError(Error)
}

struct APIClient {

    static func fetchData(from urlString: String) async -> Result<Data, Error> {
        guard let url = URL(string: urlString) else {
            return .failure(APIError.invalidURL)
        }

        do {
            let (data, response) = try await URLSession.shared.data(from: url)

            guard let httpResponse = response as? HTTPURLResponse else {
                return .failure(APIError.invalidResponse)
            }

            guard (200...299).contains(httpResponse.statusCode) else {
                return .failure(APIError.httpError(statusCode: httpResponse.statusCode))
            }

            return .success(data)
        } catch {
            return .failure(error)
        }
    }
}
```

**Uso:**

```swift
Task {
    let result = await APIClient.fetchData(from: "https://api.example.com/data")

    switch result {
    case .success(let data):
        print("Recibidos \(data.count) bytes")
    case .failure(let error):
        print("Error: \(error.localizedDescription)")
    }
}
```

**Variante con genérico + decodificación:**

```swift
static func fetch<T: Decodable>(_ type: T.Type, from urlString: String, decoder: JSONDecoder = JSONDecoder()) async -> Result<T, Error> {
    let dataResult = await fetchData(from: urlString)

    switch dataResult {
    case .success(let data):
        do {
            let decoded = try decoder.decode(T.self, from: data)
            return .success(decoded)
        } catch {
            return .failure(APIError.decodingError(error))
        }
    case .failure(let error):
        return .failure(error)
    }
}
```

